return items.map((item) => {
  const r = item.json;
  const mapped = {
    timestamp_formulario: r['Carimbo de data/hora'] || '',
    email_responsavel: r['Endereço de e-mail'] || '',
    responsavel_preenchimento: r['Responsável pelo preenchimento?'] || '',
    telefone_responsavel: r['Telefone do Responsável'] || '',
    nome_completo: r['Nome do Candidato'] || '',
    numero_tre_tse: r['Número no TRE/TSE'] || '',
    cargo_disputado: r['Cargo que concorre? '] || '',
    partido: r['Partido?'] || '',
    estado_distrito: r['Estado (Quando Governador, Deputado Estadual) ou Distrital?'] || '',
    coligacao: r['Coligação (se houver)'] || '',
    bio_curta: r['Biografia resumida:'] || '',
    causas_principais: r['Principais bandeiras de campanha?'] || '',
    telefone_candidato: r['Telefone direto do candidato?'] || '',
    nome_urna: r['Como o candidato quer ser chamado? (Nome utilizado no material de campanha)'] || '',
    tom_de_voz: r['Qual o tom de comunicação desejado?'] || '',
    bordoes: r['Quais as frases de efeito e/ou bordões caracteríticos?'] || '',
    palavras_proibidas: r['Existe alguma palavra ou expressão que não deve ser utilizada?'] || '',
    preferencia_comunicacao: r['Preferência por comunicação?'] || '',
    pautas_sensiveis: r['Existe alguma pauta que o candidato evita comentar?'] || '',
    video_apresentacao: r['Existe vídeo de apresentação do candidato? Qual o link?'] || '',
    videos_propostas: r['Existem vídeos de explicação das propostas? (Links?)'] || '',
    pdfs_propostas: r['Existem arquivos em PDF das propostas completas? (links?)'] || '',
    site_campanha: r['Qual o site da Campanha?'] || '',
    redes_sociais: r['Quais a redes sociais ativas? (links?)'] || '',
    propostas_top5: r['Apresente 5 principais propostas de campanha? '] || '',
    implementacao_propostas: r['Descreva brevemente como serão implementadas? '] || '',
    areas_prioritarias: r['Quais as áreas são prioritárias? '] || '',
    material_propostas: r['Existe material disponível sobre as propostas? (pdfs, vídeos, site)'] || '',
    propostas_minorias: r['O candidato tem propostas específicas para grupos específicos ou minorias? '] || '',
    diferenciais: r['O que diferencia o candidato de seus concorrentes? '] || '',
    agenda_predefinida: r['Existe agenda de Eventos pré-definida?'] || '',
    frequencia_agenda: r['Com que frequência a agenda será atualizada? '] || '',
    debates: r['O candidato participa de debates? Quando? '] || '',
    confirmacao_eventos: r['Onde o eleitor pode confirmar presença nos eventos?'] || '',
    numero_agente_candidato: r['Qual o número que será utilizado pelo Agente do Candidato? '] || '',
    supervisor_agenda: r['Quem é o supervisor de Agenda? '] || '',
    equipe_handoff: r['Existe equipe para atendimento humano? (handoff)'] || '',
    horario_atendimento_humano: r['Qual o horário de funcionamento do atendimento humano?'] || '',
    comites_presenciais: r['Será(ão) montado(s) comitês presenciais? '] || '',
    canais_ids: r['Quais são os canais de atuação e os respectivos Ids? '] || '',
    numero_central_comite: r['Qual o número da central de atendimento ou comitê?'] || '',
    meta_contatos_whatsapp: r['Qual a meta de contatos para o WhatsApp? (Agente de IA)'] || '',
    meta_conversao_votos: r['Qual é a meta de conversão em votos (%)?'] || '',
    canais_divulgacao_whatsapp: r['Em quantos canais será divulgado o número do WhatsApp - Agente político???'] || '',
    base_contatos: r['Existe base de contatos? Quantos? '] || '',
    estrategia_indecisos: r['Qual a sua estratégia para identificar indecisos? '] || '',
    experiencia_politica: r['Qual a sua experiência política? '] || '',
    porque_votar: r['Por que devo votar em você?'] || '',
    financiamento_propostas: r['Como vai financiar suas propostas?'] || '',
    posicao_governo_federal: r['Qual sua posição sobre o governo federal? '] || '',
    posicao_governo_estadual: r['Qual sua posição sobre o governo estadual? '] || '',
    opiniao_senadores: r['Qual sua opinião sobre o trabalho dos Senadores? '] || '',
    opiniao_deputados: r['Qual sua opinião sobre o trabalho dos deputados (Estaduais/Distritais)'] || '',
    opiniao_stf: r['Qual a sua opinião sobre o Supremo Tribunal Federal? '] || '',
    historico_cassacao: r['Você já foi cassado? Por quê?'] || '',
    participar_campanha: r['Como posso fazer parte de sua campanha? '] || '',
    opiniao_cpis: r['Qual é sua opinião sobre o resultado das CPIs? '] || '',
    diferenca_mandato: r['Em que você vai ser diferente durante seu mandato?'] || '',
    aderencia_lgpd: r['Quer que seu agente atenda a LGPD?'] || '',
    permitir_exclusao_dados: r['Quer permitir ao seu eleitor que seus dados sejam deletados se ele desejar?'] || '',
    responsavel_conformidade: r['Quem é o responsável pela conformidade legal da campanha? (nome e telefone)'] || ''
  };
  const id = (mapped.numero_tre_tse || mapped.nome_urna || mapped.nome_completo || 'candidato').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const perfil = `# Perfil do Candidato

## Identificacao
- id_candidato: ${id}
- nome_completo: ${mapped.nome_completo}
- nome_urna: ${mapped.nome_urna}
- numero_tre_tse: ${mapped.numero_tre_tse}
- partido: ${mapped.partido}
- cargo_disputado: ${mapped.cargo_disputado}
- estado_distrito: ${mapped.estado_distrito}
- coligacao: ${mapped.coligacao}

## Responsavel pelo Cadastro
- responsavel_preenchimento: ${mapped.responsavel_preenchimento}
- telefone_responsavel: ${mapped.telefone_responsavel}
- email_responsavel: ${mapped.email_responsavel}

## Narrativa e Posicionamento
- bio_curta: ${mapped.bio_curta}
- causas_principais: ${mapped.causas_principais}
- tom_de_voz: ${mapped.tom_de_voz}
- bordoes: ${mapped.bordoes}
- palavras_proibidas: ${mapped.palavras_proibidas}
- preferencia_comunicacao: ${mapped.preferencia_comunicacao}
- pautas_sensiveis: ${mapped.pautas_sensiveis}
- diferenciais: ${mapped.diferenciais}
- experiencia_politica: ${mapped.experiencia_politica}
- porque_votar: ${mapped.porque_votar}
- diferenca_mandato: ${mapped.diferenca_mandato}

## Propostas
- propostas_top5: ${mapped.propostas_top5}
- implementacao_propostas: ${mapped.implementacao_propostas}
- areas_prioritarias: ${mapped.areas_prioritarias}
- material_propostas: ${mapped.material_propostas}
- propostas_minorias: ${mapped.propostas_minorias}
- financiamento_propostas: ${mapped.financiamento_propostas}

## Conteudos e Canais
- video_apresentacao: ${mapped.video_apresentacao}
- videos_propostas: ${mapped.videos_propostas}
- pdfs_propostas: ${mapped.pdfs_propostas}
- site_campanha: ${mapped.site_campanha}
- redes_sociais: ${mapped.redes_sociais}

## Agenda e Operacao
- agenda_predefinida: ${mapped.agenda_predefinida}
- frequencia_agenda: ${mapped.frequencia_agenda}
- debates: ${mapped.debates}
- confirmacao_eventos: ${mapped.confirmacao_eventos}
- numero_agente_candidato: ${mapped.numero_agente_candidato}
- supervisor_agenda: ${mapped.supervisor_agenda}
- equipe_handoff: ${mapped.equipe_handoff}
- horario_atendimento_humano: ${mapped.horario_atendimento_humano}
- comites_presenciais: ${mapped.comites_presenciais}
- canais_ids: ${mapped.canais_ids}
- numero_central_comite: ${mapped.numero_central_comite}

## Metas de Funil
- meta_contatos_whatsapp: ${mapped.meta_contatos_whatsapp}
- meta_conversao_votos: ${mapped.meta_conversao_votos}
- canais_divulgacao_whatsapp: ${mapped.canais_divulgacao_whatsapp}
- base_contatos: ${mapped.base_contatos}
- estrategia_indecisos: ${mapped.estrategia_indecisos}

## Posicionamentos Sensiveis
- posicao_governo_federal: ${mapped.posicao_governo_federal}
- posicao_governo_estadual: ${mapped.posicao_governo_estadual}
- opiniao_senadores: ${mapped.opiniao_senadores}
- opiniao_deputados: ${mapped.opiniao_deputados}
- opiniao_stf: ${mapped.opiniao_stf}
- historico_cassacao: ${mapped.historico_cassacao}
- opiniao_cpis: ${mapped.opiniao_cpis}

## Mobilizacao e Compliance
- participar_campanha: ${mapped.participar_campanha}
- aderencia_lgpd: ${mapped.aderencia_lgpd}
- permitir_exclusao_dados: ${mapped.permitir_exclusao_dados}
- responsavel_conformidade: ${mapped.responsavel_conformidade}
`;
  return {
    json: {
      ...mapped,
      raw_form_data: r,
      id_candidato_normalizado: id,
      arquivo_markdown: `${id}.md`,
      perfil_markdown: perfil,
      status_intake: 'normalizado'
    }
  };
});
